.fig{position:relative}
.zoomhint{display:none}
@media (max-width:700px){
  .fig:not(.fig-sm):has(> svg){cursor:zoom-in}
  .fig:not(.fig-sm):has(> svg){display:flex;flex-direction:column}
  .fig:not(.fig-sm):has(> svg) > svg{order:0}
  .fig:not(.fig-sm):has(> svg) .zoomhint{order:1;display:inline-flex;align-self:center;align-items:center;gap:5px;margin-top:8px;font-size:12px;color:var(--blue-ink);background:var(--blue-soft);border-radius:999px;padding:4px 11px;pointer-events:none}
  .fig:not(.fig-sm):has(> svg) figcaption{order:2}
}
