.addph{width:150px;aspect-ratio:4/3;border:1.5px dashed color-mix(in srgb,var(--amber) 55%,transparent);border-radius:10px;background:transparent;color:var(--amber);cursor:pointer;font-size:12.5px;font-weight:500;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;padding:8px;text-align:center}
.addph span{font-size:22px;line-height:1}
.addph:hover{background:var(--amber-soft)}
.pair{display:grid;grid-template-columns:1fr auto 1fr;gap:12px;align-items:start;margin-top:14px;padding-top:12px;border-top:1px solid var(--line)}
.pair-col{min-width:0}
.pair-arrow{color:var(--dim);font-size:22px;padding-top:40px}
.pair-h{font-size:11.5px;text-transform:uppercase;letter-spacing:.1em;color:var(--muted);font-weight:600}
.pair-h.prob{color:var(--warn)} .pair-h.sol{color:var(--ok)}
.pair .nov{font-size:13px;margin-top:6px}
.symvid{margin-top:14px;padding-top:12px;border-top:1px solid var(--line);display:flex;flex-direction:column;gap:8px}
.addwrap summary{cursor:pointer;color:var(--blue-ink);font-size:13.5px;font-weight:500}
.lightbox{position:fixed;inset:0;z-index:20;background:rgba(5,8,10,.92);display:flex;align-items:center;justify-content:center;padding:max(16px,env(safe-area-inset-top,0px)) max(16px,env(safe-area-inset-right,0px)) max(16px,env(safe-area-inset-bottom,0px)) max(16px,env(safe-area-inset-left,0px))}
.lightbox[hidden]{display:none!important}
.lbin{display:flex;flex-direction:column;align-items:center;gap:10px;max-width:100%;max-height:100%}
.lbin img{max-width:100%;max-height:80vh;border-radius:10px;object-fit:contain}
.lbin p{margin:0;color:#E7EDF2;text-align:center}
.lbx{position:absolute;top:calc(12px + env(safe-area-inset-top,0px));right:calc(12px + env(safe-area-inset-right,0px));width:44px;height:44px;border-radius:50%;border:0;background:rgba(255,255,255,.12);color:#fff;font-size:26px;cursor:pointer}
.vidblk:empty{display:none}
.footlinks{display:flex;flex-wrap:wrap;gap:8px;align-items:center;justify-content:center;margin-top:16px;color:var(--dim);font-size:13.5px}
.footlinks a{color:var(--blue-ink);text-decoration:none;padding:9px 4px}
.footlinks .linkbtn{margin:0}
.about .entry p + p{margin-top:8px}
.mcap{font-size:11px;text-transform:uppercase;letter-spacing:.1em;color:var(--muted);padding:8px 12px 4px}
.engs{display:flex;flex-direction:column;gap:2px}
.mstep{padding-bottom:6px;border-bottom:1px solid var(--line);margin-bottom:4px}
.mcap{display:flex;align-items:center;gap:8px}
.mcap span{display:inline-grid;place-items:center;width:18px;height:18px;border:1px solid var(--amber);color:var(--amber);font:600 11px var(--f-mono);border-radius:2px}
.mfams{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:2px}
.mfams button small{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.fammenu button[aria-pressed="true"]{background:var(--surface);box-shadow:inset 3px 0 0 var(--amber)}
.mseg{display:grid;grid-template-columns:1fr 1fr;gap:6px;padding:2px 6px}
