.mnote{margin:6px 12px 0;font-size:12.5px;color:var(--dim)}
.mdone{padding:6px 6px 4px}
.mdone .btn{width:100%}
.enghelp{margin:6px 6px 4px;padding:10px 12px;border-radius:10px;background:var(--surface);font-size:13px}
.enghelp summary{cursor:pointer;color:var(--amber);font-weight:600}
.enghelp ul{margin:8px 0 0;padding-left:18px;display:flex;flex-direction:column;gap:6px;color:var(--ink)}
.fammenu{max-height:min(70vh,560px);overflow-y:auto}
.cookiebar{position:fixed;left:50%;transform:translateX(-50%);bottom:calc(16px + env(safe-area-inset-bottom,0px));z-index:14;width:min(640px,calc(100% - 32px));display:flex;gap:12px;align-items:center;background:var(--raised);border:1px solid var(--line-2);border-radius:14px;padding:12px 14px;box-shadow:0 14px 40px rgba(0,0,0,.45)}
