.cookiebar .btn{flex:none}
@media (max-width:640px){.cookiebar{bottom:calc(78px + env(safe-area-inset-bottom,0px));flex-direction:column;align-items:stretch}}
.toast{position:fixed;left:50%;bottom:calc(24px + env(safe-area-inset-bottom,0px));transform:translate(-50%,20px);opacity:0;pointer-events:none;background:var(--raised);border:1px solid var(--line-2);color:var(--ink);padding:10px 16px;border-radius:12px;font-size:14px;z-index:15;max-width:calc(100% - 32px);transition:opacity .2s,transform .2s}
.toast.show{opacity:1;transform:translate(-50%,0)} .toast.err{border-color:var(--warn);color:var(--warn)}

/* выбор машины */
.famsel{position:relative}
.famrow{display:flex;align-items:center;gap:12px;min-width:0}
.fambtn{display:inline-flex;align-items:center;gap:6px;flex:none;border:0;background:var(--blue);color:#fff;border-radius:10px;padding:8px 12px 8px 14px;cursor:pointer;font-weight:600;font-size:14px}
.fambtn svg{width:16px;height:16px;stroke:#fff}
.fambtn:hover{filter:brightness(1.1)}
.famcur{display:flex;flex-direction:column;gap:1px;min-width:0;cursor:default;line-height:1.25}
.famcur b{font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--ink)}
.famcur small{color:var(--amber);font-size:12.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
.fammenu{position:absolute;top:calc(100% + 6px);left:0;z-index:8;width:min(520px,100%);background:var(--raised);border:1px solid var(--line-2);border-radius:12px;padding:6px;box-shadow:0 18px 40px rgba(0,0,0,.45);display:flex;flex-direction:column;gap:2px}
.fammenu button{display:flex;flex-direction:column;align-items:flex-start;border:0;background:none;color:var(--ink);text-align:left;padding:9px 12px;border-radius:8px;cursor:pointer}
.fammenu button small{color:var(--muted);font-size:12.5px}
.fammenu button:hover{background:var(--surface)}
.fammenu button[aria-pressed="true"]{background:var(--blue-soft)}
.fammenu button[aria-pressed="true"] b{color:var(--blue-ink)}
/* группы */
.group{margin-bottom:22px}
.gh{display:flex;align-items:center;gap:8px;font:400 17px/1.2 var(--f-display);letter-spacing:.02em;margin:0 0 10px}
.gh span{font:500 12px var(--f-body);color:var(--muted);background:var(--raised);border:1px solid var(--line);border-radius:999px;padding:1px 8px}
/* цифры */
.numgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:12px}
.numgrid .plate{margin:0}
.numdl{grid-template-columns:1fr!important}
.numdl div{display:grid;grid-template-columns:minmax(110px,40%) 1fr;gap:10px;padding-top:8px;border-top:1px solid var(--line)}
.numdl div:first-child{border-top:0;padding-top:0}
.numdl dt{margin:0}
.numdl dd{font-size:15px!important}
/* старт */
.startbtn{display:flex;align-items:center;gap:12px;width:100%;margin:0 0 20px;padding:12px 16px;border:0;border-radius:var(--r);background:var(--amber);color:var(--amber-ink);cursor:pointer;text-align:left}
.startbtn svg{width:30px;height:30px;fill:var(--amber-ink);flex:none}
.startbtn span{display:flex;flex-direction:column}
.startbtn b{font-size:17px} .startbtn small{font-size:13px;opacity:.75}
.startbtn:hover{filter:brightness(1.06)}
/* пошаговый режим */
body.locked{overflow:hidden}
.doer{position:fixed;inset:0;z-index:18;background:var(--bg);display:flex;flex-direction:column;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}
.doer[hidden]{display:none!important}
.dtop{display:flex;align-items:center;gap:12px;padding:12px max(16px,env(safe-area-inset-right,0px)) 10px max(16px,env(safe-area-inset-left,0px));border-bottom:1px solid var(--line);background:var(--surface)}
.dx{width:40px;height:40px;border-radius:50%;border:1px solid var(--line-2);background:var(--raised);color:var(--ink);font-size:24px;line-height:1;cursor:pointer;flex:none}
.dtitle{display:flex;flex-direction:column;min-width:0}
.dtitle b{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dtitle small{color:var(--amber);font-weight:600}
.dbar{height:4px;background:var(--line)} .dbar span{display:block;height:100%;background:var(--amber);transition:width .25s}
.dbody{flex:1;overflow-y:auto;padding:20px max(16px,env(safe-area-inset-right,0px)) 20px max(16px,env(safe-area-inset-left,0px))}
.dbody > *{max-width:720px;margin-left:auto;margin-right:auto}
.dnums{margin-bottom:18px;background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:10px 14px}
.dnums summary{cursor:pointer;color:var(--amber);font-weight:600;font-size:14px}
.dnums dl{display:grid;gap:8px;margin:10px 0 0}
.dnums dt{font-size:12.5px;color:var(--muted)} .dnums dd{margin:0;font-size:14px}
.dstep{display:flex;flex-direction:column;gap:16px}
.dnum{width:56px;height:56px;border-radius:50%;border:3px solid var(--amber);color:var(--amber);display:grid;place-items:center;font:24px var(--f-display)}
.dtext{font-size:22px;line-height:1.45;margin:0}
.dtext .n{font-size:20px}
.dstep .ph,.dstep .addph{width:min(320px,100%)}
.dnav{display:flex;gap:10px;padding:12px max(16px,env(safe-area-inset-right,0px)) 14px max(16px,env(safe-area-inset-left,0px));border-top:1px solid var(--line);background:var(--surface)}
.big{padding:16px 18px;font-size:17px;border-radius:14px}
.dnav .ghost{flex:0 0 auto}
.dnav .btn{flex:1}
.btn.amber{background:var(--amber);color:var(--amber-ink)}
.ghost:disabled{opacity:.35;cursor:default}
.dfinish{display:flex;flex-direction:column;align-items:center;text-align:center;gap:12px;padding-top:40px}
.dfinish h3{font:26px var(--f-display);margin:0} .dfinish p{margin:0;color:var(--muted)}
.dfinish .big{width:min(360px,100%)}
.dcheck{width:84px;height:84px;border-radius:50%;background:color-mix(in srgb,var(--ok) 18%,transparent);display:grid;place-items:center}
.dcheck svg{width:46px;height:46px;fill:none;stroke:var(--ok);stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round}

@media (max-width:640px){
  .tabs{display:none}
  .features{grid-template-columns:repeat(3,1fr);gap:8px}
  .feature{flex-direction:column;align-items:flex-start;gap:8px;padding:10px}
  .feature .ico{width:34px;height:34px;border-radius:9px}
  .feature .ico svg{width:19px;height:19px}
  .feature small{display:none}
  .feature b{font-size:13.5px;line-height:1.25}
  .dtext{font-size:20px}
  .numdl div{grid-template-columns:1fr;gap:0}
  .pair{grid-template-columns:1fr}
  .pair-arrow{display:none}
  .ph,.addph{width:calc(50% - 4px)}
  .toast{bottom:calc(84px + env(safe-area-inset-bottom,0px))}
  .tg span{display:none}
  .tg{padding:7px}
  nav.bottom{display:flex;position:fixed;left:0;right:0;bottom:0;z-index:6;background:color-mix(in srgb,var(--surface) 94%,transparent);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);border-top:1px solid var(--line);padding:6px max(8px,env(safe-area-inset-right,0px)) calc(6px + env(safe-area-inset-bottom,0px)) max(8px,env(safe-area-inset-left,0px))}
  nav.bottom button{flex:1;display:flex;flex-direction:column;align-items:center;gap:3px;border:0;background:none;color:var(--muted);font-size:11.5px;padding:6px 0;cursor:pointer;border-radius:10px}
  nav.bottom svg{width:22px;height:22px;stroke:currentColor}
  nav.bottom button[aria-selected="true"]{color:var(--amber)}
  main{padding-bottom:110px}
  .types li{grid-template-columns:1fr;gap:2px}
  .detail h2{font-size:22px}
  .brand .sub{display:none}
}
@media (max-width:640px){
  .list{gap:10px}
  .list .card{display:grid;grid-template-columns:42px 1fr;column-gap:14px;row-gap:3px;padding:14px;align-items:start}
  .list .card > .ico{grid-row:1 / span 3;width:42px;height:42px;border-radius:11px}
  .list .card > :not(.ico){grid-column:2}
  .list .card h3{margin:0;font-size:16px}
  .list .card p{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
  .list .card .meta{padding-top:5px}
}
@media (prefers-reduced-motion:no-preference){.card,.fam button,.tools button{transition:background-color .15s,border-color .15s,color .15s}}


/* ===== Строгий стиль: сталь, жёлтый «осторожно», прямые углы ===== */
:root{
  --bg:#0A0C0E; --peg:#15191D; --surface:#101316; --raised:#171B1F; --line:#252A30; --line-2:#3A4148;
  --ink:#EEF0F2; --muted:#979EA6; --dim:#646B73;
  --blue:#2A3037; --blue-ink:#D5DBE0; --blue-soft:#1B2026;
  --amber:#FFB400; --amber-ink:#0A0C0E; --amber-soft:#211A06;
  --warn:#FF5A3C; --ok:#7BC96F;
  --f-head:"Oswald","Arial Narrow","Roboto Condensed",system-ui,sans-serif;
  --r:3px;
  --hazard:repeating-linear-gradient(-45deg,var(--amber) 0 9px,#0A0C0E 9px 18px);
}
body{background-image:linear-gradient(var(--peg) 1px,transparent 1px),linear-gradient(90deg,var(--peg) 1px,transparent 1px);background-size:40px 40px}
a{color:var(--amber)}

/* шапка */
header{background:var(--surface);backdrop-filter:none;-webkit-backdrop-filter:none;border-bottom:0}
header::after{content:"";display:block;height:5px;background:var(--hazard)}
.logo{border-radius:2px}
.brand h1{font:700 27px/1 var(--f-head);text-transform:uppercase;letter-spacing:.04em}
.brand .sub{font:500 11.5px var(--f-mono);text-transform:uppercase;letter-spacing:.08em;color:var(--dim)}
.tg{border-radius:2px;text-transform:uppercase;font:500 12px var(--f-mono);letter-spacing:.06em;border-color:var(--line-2)}
.tg:hover{color:var(--amber);border-color:var(--amber)}
.fambtn{background:var(--amber);color:var(--amber-ink);border-radius:2px;font:600 15px var(--f-head);text-transform:uppercase;letter-spacing:.05em}
.fambtn svg{stroke:var(--amber-ink)}
.famcur b,.famcur{font-family:var(--f-head);letter-spacing:.02em}
.fammenu{border-radius:3px;border-color:var(--amber)}
.fammenu button{border-radius:2px}
.tabs button{font:500 15px var(--f-head);text-transform:uppercase;letter-spacing:.07em}
.tabs button[aria-selected="true"]{border-bottom-width:3px}

/* поиск, плашки, кнопки */
.search input{border-radius:2px;background:var(--bg);border-color:var(--line-2)}
.search input:focus{border-color:var(--amber);outline:0}
.pill{border-radius:2px;font:500 11px/1.6 var(--f-mono);text-transform:uppercase;letter-spacing:.05em}
.gh{font:600 19px/1.2 var(--f-head);text-transform:uppercase;letter-spacing:.06em;padding-left:12px;border-left:4px solid var(--amber)}
.gh span{border-radius:2px;font-family:var(--f-mono)}
.btn{border-radius:2px;background:var(--amber);color:var(--amber-ink);font-family:var(--f-head);text-transform:uppercase;letter-spacing:.05em;font-size:15px}
.ghost,.back{border-radius:2px}
.back{font:500 13.5px var(--f-head);text-transform:uppercase;letter-spacing:.06em;background:transparent}
.back:hover{border-color:var(--amber);color:var(--amber)}
.linkbtn{color:var(--amber)}

/* карточки */
.card,.entry,.plate,.fig,.tgcard,.artstrip{border-radius:3px}
.card{border-color:var(--line-2);background:var(--surface);position:relative}
.card:hover{border-color:var(--amber);background:var(--raised)}
.card h3{font:600 18px/1.2 var(--f-head);text-transform:uppercase;letter-spacing:.03em}
.ico{border-radius:2px;background:var(--raised);border:1px solid var(--line-2)}
.ico svg{stroke:var(--amber)}
.feature,.logbtn{border-radius:3px;background:var(--raised);border:1px solid var(--line-2);border-top:3px solid var(--amber)}
.feature:hover,.logbtn:hover{background:var(--amber-soft)}
.feature .ico,.logbtn .ico{border:0}
.feature b,.logbtn b,.artstrip b,.tgcard b{font:600 16.5px/1.2 var(--f-head);text-transform:uppercase;letter-spacing:.04em}
.artstrip .ico{background:var(--raised)}
.artstrip .ico svg{stroke:var(--amber)}
.tgcard:hover,.artstrip:hover{border-color:var(--amber)}
.entry h3{font:600 20px/1.2 var(--f-head);text-transform:uppercase;letter-spacing:.04em}
.sym h3{font:600 18px/1.25 var(--f-head);text-transform:uppercase;letter-spacing:.03em}

/* страница работы */
.detail h2,.dhead h2{font:700 30px/1.1 var(--f-head);text-transform:uppercase;letter-spacing:.03em}
.dhead .ico{border-radius:2px}
.startbtn{border-radius:2px;background:var(--amber);position:relative;overflow:hidden}
.startbtn b{font:700 20px/1.1 var(--f-head);text-transform:uppercase;letter-spacing:.06em}
.startbtn::after{content:"";position:absolute;right:0;top:0;bottom:0;width:56px;background:var(--hazard);opacity:.9;-webkit-mask:linear-gradient(90deg,transparent,#000 60%);mask:linear-gradient(90deg,transparent,#000 60%)}
.plate{background:var(--raised);border:1px solid var(--line-2);border-left:4px solid var(--amber)}
.plate .cap{font-family:var(--f-mono);letter-spacing:.08em}
.plate .cap::before{border-radius:0;box-shadow:none}
.blk h4{font:500 12px var(--f-mono);letter-spacing:.12em;color:var(--amber);display:flex;align-items:center;gap:10px}
.blk h4::after{content:"";flex:1;height:1px;background:var(--line-2)}
.tools button,.tools span{border-radius:2px}
.tools button{color:var(--ink);border-color:var(--line-2);background:var(--raised)}
.tools button:hover{border-color:var(--amber);background:var(--raised)}
ol.steps li::before{border-radius:2px;background:var(--amber);color:var(--amber-ink);border-color:var(--amber);font:700 16px/28px var(--f-head)}
ol.steps li:not(:last-child)::after{background:var(--line-2)}
.n{border-radius:2px}
.warn{border-radius:3px;background:color-mix(in srgb,var(--warn) 10%,var(--surface));border:1px solid color-mix(in srgb,var(--warn) 45%,transparent);border-left:6px solid var(--warn)}
.warn::before{border-radius:2px}
.tip{border-radius:2px;border-left:4px solid var(--amber)}
.fig{background:var(--bg)}
.zoomhint{border-radius:2px!important;color:var(--amber)!important;background:var(--amber-soft)!important;font-family:var(--f-mono)!important;text-transform:uppercase}

/* нижнее меню на телефоне */
nav.bottom{background:var(--surface);backdrop-filter:none;-webkit-backdrop-filter:none;border-top:2px solid var(--line-2)}
nav.bottom button{border-radius:0;font-family:var(--f-head);text-transform:uppercase;letter-spacing:.06em}
nav.bottom button[aria-selected="true"]{box-shadow:inset 0 3px 0 var(--amber)}
.cookiebar{border-radius:3px;border-top:3px solid var(--amber)}

/* ===== Сдержаннее: меньше жёлтого, без «игрушечности» ===== */
:root{--amber:#E8A317; --amber-soft:#1E1909; --hazard:repeating-linear-gradient(-45deg,#B98212 0 7px,#0A0C0E 7px 14px)}
header::after{height:3px;opacity:.85}
.startbtn::after{display:none}
.startbtn{background:var(--amber);box-shadow:inset 0 -3px 0 rgba(0,0,0,.25)}
.fambtn{background:transparent;color:var(--amber);border:1px solid var(--amber)}
.fambtn svg{stroke:var(--amber)}
.logo{background:var(--amber)}
.ico svg{stroke:var(--ink)}
.ico{background:transparent}
.feature .ico,.logbtn .ico{background:transparent;border:1px solid var(--line-2)}
.feature .ico svg,.logbtn .ico svg{stroke:var(--amber)}
.feature,.logbtn{border-top:1px solid var(--line-2);border-left:3px solid var(--amber);background:var(--surface)}
.feature:hover,.logbtn:hover{background:var(--raised);border-color:var(--line-2);border-left-color:var(--amber)}
.card:hover{border-color:var(--line-2);background:var(--raised);box-shadow:inset 3px 0 0 var(--amber)}
.card h3,.feature b,.logbtn b,.artstrip b,.tgcard b,.sym h3{text-transform:none;letter-spacing:.01em;font-weight:500}
.card h3{font-size:19px}
.gh{border-left-width:3px}
ol.steps li::before{background:transparent;color:var(--amber);border:2px solid var(--amber)}
.pill.lvl1{color:var(--ok)} .pill.lvl2{color:var(--amber)}
.plate{border-left-width:3px}
body{background-size:48px 48px}

/* ===== Строгий спокойный стиль (обе темы) ===== */
header::after{display:none}
body{background-image:none}
.brand h1{text-transform:none;letter-spacing:.01em}
.brand .sub{text-transform:none;letter-spacing:.02em;font:500 12.5px var(--f-body);color:var(--muted)}
.tabs button,.fambtn,.back,.btn,nav.bottom button,.fseg button,.gh,.detail h2,.dhead h2,.startbtn b,.entry h3,.feature b,.logbtn b,.artstrip b,.tg{text-transform:none;letter-spacing:.01em}
.tabs button{font:500 15.5px var(--f-body)}
nav.bottom button{font:500 11px var(--f-body)}
.fseg button{font:500 14px var(--f-body)}
.gh{font:600 18px/1.2 var(--f-body);border-left:0;padding-left:0}
.detail h2.gh{font:600 18px/1.2 var(--f-body);text-transform:none;letter-spacing:0}
.tg{font:500 13px var(--f-body)}
.feature,.logbtn{border:1px solid var(--line-2);border-top:1px solid var(--line-2);border-left:1px solid var(--line-2)}
.feature .ico svg,.logbtn .ico svg{stroke:var(--amber)}
.card:hover{box-shadow:none;border-color:var(--amber)}
.plate{border-left:1px solid var(--line-2)}
.pill.lvl1,.pill.lvl2{color:var(--muted)}
/* страница работы — как в руководстве */
.jcrumbs{display:flex;align-items:center;gap:6px;flex-wrap:wrap;font-size:13.5px;color:var(--dim);margin-bottom:10px}
.jcrumbs button{border:0;background:none;padding:4px 0;color:var(--amber);cursor:pointer;font:inherit;font-weight:500}
.jtitle{font:700 28px/1.15 var(--f-head,var(--f-body))!important;margin:0 0 8px!important;letter-spacing:.005em!important}
.job .lead{margin-bottom:16px}
.passport{border:1px solid var(--line-2);border-radius:var(--r);background:var(--surface);margin-bottom:16px}
.pp-row{padding:12px 14px;border-top:1px solid var(--line)}
.pp-row:first-child{border-top:0}
.pp-top{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px 18px}
.pp-k{display:block;font:500 11px var(--f-mono);text-transform:uppercase;letter-spacing:.07em;color:var(--dim);margin-bottom:5px}
.pp-v{display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-size:14.5px}
.diff{display:inline-flex;gap:3px}
.diff i{width:14px;height:8px;border-radius:1px;background:var(--line-2)}
.diff i.on{background:var(--amber)}
.pp-nums{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px 18px;margin:0}
.pp-nums dt{font-size:12.5px;color:var(--muted)}
.pp-nums dd{margin:2px 0 0;font:500 16px/1.3 var(--f-mono);color:var(--amber)}
.pp-nums dd.txt{font:500 14px/1.45 var(--f-body);color:var(--ink)}
.cattbl{width:100%;border-collapse:collapse;margin-top:8px;font-size:13.5px}
.cattbl td{padding:6px 0;border-top:1px solid var(--line)}
.cattbl td.mono{white-space:nowrap;padding-left:12px;font:500 13.5px var(--f-mono);text-align:right;color:var(--ink)}
.jsec{margin-top:22px}
.jh{display:flex;align-items:center;gap:10px;font:600 19px/1.25 var(--f-body);margin:0 0 12px;padding-bottom:8px;border-bottom:2px solid var(--ink)}
.jh span{display:inline-grid;place-items:center;min-width:26px;height:26px;padding:0 6px;background:var(--ink);color:var(--bg);font:600 13px var(--f-mono);border-radius:2px}
.keytag{display:inline-block;margin-left:8px;font:500 11.5px var(--f-mono);color:var(--muted);border:1px solid var(--line-2);border-radius:2px;padding:1px 6px;vertical-align:1px;white-space:nowrap}
.callout{margin:8px 0 0;padding:8px 12px;font-size:14px;border-radius:2px;border-left:3px solid}
.callout.att{background:var(--amber-soft);border-color:var(--amber)}
.callout.dang{background:color-mix(in srgb,var(--warn) 10%,var(--surface));border-color:var(--warn)}
.callout b{font-weight:700}
.job > .callout{margin-top:18px}
.figwrap{margin-bottom:14px}
.fignum{font:500 11.5px var(--f-mono);text-transform:uppercase;letter-spacing:.07em;color:var(--dim);margin-bottom:5px}
.mist{margin:0;padding-left:20px;display:flex;flex-direction:column;gap:6px}
.srcs{margin:0;padding-left:20px;display:flex;flex-direction:column;gap:4px;font-size:14px}
.legend li{break-inside:avoid}
.legend{margin:8px 0 0;padding-left:20px;text-align:left;columns:2;column-gap:24px;font-size:13px;color:var(--ink)}
.tl-body{fill:none;stroke:var(--ink);stroke-width:1.6}
:root{--tl-fill:#20262c;--tl-fill2:#2c333b;--tl-pad:#6b5a43;--tl-oil:#b98a2e;--tl-cool:#b34d6d;--tl-brk:#b8a45c;--tl-glass:#1b2836}
:root[data-theme="light"]{--tl-fill:#EDEAE3;--tl-fill2:#D9D5CB;--tl-pad:#C9B596;--tl-oil:#D7A84A;--tl-cool:#E79AB0;--tl-brk:#E4D598;--tl-glass:#E6EEF6}
.tl-fill{fill:var(--tl-fill)} .tl-fill2{fill:var(--tl-fill2)}
.fx-zb{fill:color-mix(in srgb,var(--ok) 70%,transparent)}
.fx-bluef{fill:var(--ink)}
.fx-filterf{fill:var(--tl-fill2);stroke:var(--ink);stroke-width:1.4}
.tl-xs{fill:var(--muted);font:500 10px var(--f-body)}
.stepsvg .tl-v{font-size:12px}
.tl-handle{stroke:var(--ink);stroke-width:7;stroke-linecap:round;fill:none;opacity:.85}
.tl-oring{fill:none;stroke:var(--amber);stroke-width:4}
.tl-oilline{stroke:var(--tl-oil);stroke-width:4;fill:none;stroke-linecap:round}
.tl-coolline{stroke:var(--tl-cool);stroke-width:4;fill:none;stroke-linecap:round}
.tl-wiperarm{stroke:var(--ink);stroke-width:6;stroke-linecap:round}
.tl-wire{stroke:var(--ink);stroke-width:5;fill:none;stroke-linecap:round}
.tl-tyre{fill:var(--tl-fill2);stroke:var(--ink);stroke-width:1.6}
.tl-spoke{stroke:var(--ink);stroke-width:5;stroke-linecap:round;opacity:.8}
.tl-beam{stroke:var(--amber);stroke-width:1.4;stroke-dasharray:4 3}
.tl-warnl{fill:none;stroke:var(--warn);stroke-width:2}
.tl-jack{stroke:var(--ink);stroke-width:4;fill:none;stroke-linejoin:round}
.tl-needle{stroke:var(--ink);stroke-width:2.5}
.tl-clamp{stroke:var(--ink);stroke-width:5;fill:none;stroke-linecap:round}
.tl-pedalarm{stroke:var(--ink);stroke-width:7;stroke-linecap:round}
.tl-pipeT{stroke:var(--muted);stroke-width:7;stroke-linecap:round}
.tl-lcdT{fill:#cfd8c0;stroke:var(--ink);stroke-width:1.2}
.tl-lcdt{fill:#1a2a10;font:600 17px var(--f-mono)}
.tl-probeR{stroke:#C0392B;stroke-width:3;fill:none}
.tl-probeB{stroke:var(--ink);stroke-width:3;fill:none}
.tl-redf{fill:#C0392B}
.tl-term{fill:#fff;font:700 13px var(--f-body);text-anchor:middle}
.tl-term2{fill:var(--ink);font:700 13px var(--f-body);text-anchor:middle}
.tl-spring{stroke:var(--ink);stroke-width:3;fill:none}
.tl-bar{stroke:var(--ink);stroke-width:14;fill:none;stroke-linecap:round;opacity:.25}
.tl-slot{stroke:var(--ink);stroke-width:3;fill:none;stroke-linecap:round}
.tl-hosethick{stroke:var(--ink);stroke-width:14;fill:none;stroke-linecap:round;opacity:.35}
.tl-stickT{stroke:var(--ink);stroke-width:3}
.tl-cableR{stroke:#C0392B;stroke-width:5;fill:none;stroke-linecap:round}
.tl-cableB{stroke:var(--ink);stroke-width:5;fill:none;stroke-linecap:round}
.stepfig svg .fx-arA{stroke:var(--amber)}

.tl-thin{stroke:var(--ink);stroke-width:1;fill:none;opacity:.75}
.tl-dot{fill:var(--ink)}
.tl-acc{stroke:var(--amber);stroke-width:2.6;fill:none;stroke-linecap:round}
.tl-accline{stroke:var(--amber);stroke-width:2;fill:none;stroke-dasharray:6 4}
.tl-accf{fill:var(--amber);stroke:var(--ink);stroke-width:1.2}
.tl-arrf{fill:var(--amber)}
.tl-mark{stroke:var(--amber);stroke-width:4;stroke-linecap:round}
.tl-dim{stroke:var(--ink);stroke-width:1.2;fill:none}
.tl-v{fill:var(--amber);font:600 13px var(--f-mono)}
.tl-warnt{fill:var(--warn)}
.tl-h{fill:var(--ink);font:600 14px var(--f-body)}
.tl-belt{stroke:var(--ink);stroke-width:7;fill:none;stroke-linecap:round;opacity:.8}
.tl-hose{stroke:var(--muted);stroke-width:5;fill:none;stroke-linecap:round}
.tl-hosec{stroke:var(--blue-ink);stroke-width:6;fill:none;stroke-linecap:round;opacity:.55}
.tl-pipe{stroke:var(--muted);stroke-width:6;stroke-linecap:round}
.tl-stick{stroke:var(--ink);stroke-width:5;stroke-linecap:round}
.tl-padf{fill:var(--tl-pad)} .tl-padf2{fill:var(--tl-pad);opacity:.55}
.tl-warnf{fill:var(--warn)}
.tl-oilf{fill:var(--tl-oil)} .tl-coolf{fill:var(--tl-cool)} .tl-brakef{fill:var(--tl-brk)}
.tl-glass{fill:var(--tl-glass)}
.tl-seal{fill:none;stroke:var(--amber);stroke-width:3;stroke-dasharray:2 3}
.tl-wiper{stroke:var(--ink);stroke-width:5;stroke-linecap:round}
.tl-ghost{display:none}
.figcap2{margin:6px 0 0;font-size:13px;color:var(--muted);text-align:left}
.fig figcaption{text-align:left}
.tl-part{fill:var(--surface);stroke:var(--ink);stroke-width:1.6}
.tl-part-l{stroke:var(--ink);stroke-width:1.6}
.tl-hid{stroke:var(--muted);stroke-width:1.2;stroke-dasharray:5 4;fill:none}
.tl-lead{stroke:var(--ink);stroke-width:1}
.tl-num{fill:var(--surface);stroke:var(--ink);stroke-width:1.4}
.tl-numt2{fill:var(--amber-ink);font:700 14px var(--f-mono)}
:root:not([data-theme="light"]) .tl-numt2{fill:#0A0C0E}
.tl-numt{fill:var(--ink);font:600 12px var(--f-mono)}
.tl-s{fill:var(--muted);font:500 12px var(--f-body)}
.cdiff{display:inline-flex;align-items:center;gap:6px}
.cdiff .diff i{width:10px;height:6px}
.cdiff b{font-weight:500}
.zoomhint{text-transform:none!important;font-family:var(--f-body)!important;font-size:12.5px!important}
.ghits .hits{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:8px}
.hit{display:flex;flex-direction:column;gap:2px;text-align:left;border:1px solid var(--line-2);background:var(--surface);border-radius:var(--r);padding:10px 12px;cursor:pointer;color:var(--ink)}
.hit:hover{border-color:var(--amber)}
.hit small{font:500 11px var(--f-mono);text-transform:uppercase;letter-spacing:.06em;color:var(--dim)}
.hit b{font-weight:500;font-size:14.5px}
@media (max-width:640px){.jtitle{font-size:24px!important}.legend{columns:1}.tabs button{font-size:14.5px}}

/* ===== Светлая тема «как руководство» ===== */
:root[data-theme="light"]{
  color-scheme:light;
  --bg:#F4F3EF; --peg:#E9E7E1; --surface:#FFFFFF; --raised:#F7F6F2; --sunk:#ECEAE4; --line:#E3E0D8; --line-2:#CDC9BE;
  --ink:#1A1C1F; --muted:#585D64; --dim:#80858C;
  --blue:#E9E7E1; --blue-ink:#1F4E8C; --blue-soft:#EEF2F8;
  --amber:#A35C00; --amber-ink:#FFFFFF; --amber-soft:#FBF2E2;
  --warn:#B4380F; --ok:#2E7A3A;
}
:root[data-theme="light"] html,:root[data-theme="light"] body{background:var(--bg)}
:root[data-theme="light"] header,:root[data-theme="light"] nav.bottom{background:var(--surface);border-bottom:1px solid var(--line-2)}
:root[data-theme="light"] nav.bottom{border-top:1px solid var(--line-2)}
:root[data-theme="light"] body::before{background:var(--surface)}
:root[data-theme="light"] .logo{background:var(--ink)}
:root[data-theme="light"] .logo svg{stroke:#fff}
:root[data-theme="light"] .startbtn{background:var(--ink);color:#fff;box-shadow:none}
:root[data-theme="light"] .startbtn svg{fill:#fff}
:root[data-theme="light"] .startbtn small{color:#d6d6d6}
:root[data-theme="light"] .btn{background:var(--ink);color:#fff}
:root[data-theme="light"] .fambtn{color:var(--ink);border-color:var(--ink)}
:root[data-theme="light"] .fambtn svg{stroke:var(--ink)}
:root[data-theme="light"] .tabs button[aria-selected="true"]{color:var(--ink);border-bottom-color:var(--ink)}
:root[data-theme="light"] nav.bottom button[aria-selected="true"]{color:var(--ink);box-shadow:inset 0 3px 0 var(--ink)}
:root[data-theme="light"] .fseg button[aria-selected="true"]{color:var(--ink);box-shadow:inset 0 -3px 0 var(--ink);background:var(--raised)}
:root[data-theme="light"] .ico{border-color:var(--line-2)}
:root[data-theme="light"] .ico svg{stroke:var(--ink)}
:root[data-theme="light"] .feature .ico svg,:root[data-theme="light"] .logbtn .ico svg,:root[data-theme="light"] .artstrip .ico svg{stroke:var(--amber)}
:root[data-theme="light"] .card,:root[data-theme="light"] .entry,:root[data-theme="light"] .feature,:root[data-theme="light"] .artstrip,:root[data-theme="light"] .logbtn{box-shadow:0 1px 0 rgba(0,0,0,.03)}
:root[data-theme="light"] .fig{background:var(--surface)}
:root[data-theme="light"] .search input{background:var(--surface)}
:root[data-theme="light"] .cookiebar{background:var(--surface);box-shadow:0 10px 30px rgba(0,0,0,.15)}
:root[data-theme="light"] .tools button{background:var(--surface);color:var(--ink)}
:root[data-theme="light"] .tools button.part{color:var(--amber)}
:root[data-theme="light"] .pill{background:var(--raised)}
:root[data-theme="light"] ol.steps li::before{background:var(--surface);color:var(--ink);border-color:var(--ink)}
:root[data-theme="light"] .warn{background:#FDF0EB}
:root[data-theme="light"] .tip{background:var(--amber-soft)}
:root[data-theme="light"] .lampc-ico,:root[data-theme="light"] .lamp-ico{background:#16181b}
:root[data-theme="light"] .zoomov{background:var(--bg)}
